'use strict';
const assert=require('node:assert/strict');
const {createHash}=require('node:crypto');
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
const SHA=/^[a-f0-9]{64}$/;
const OBJECTIVE='ss_listing_image_command_execution',RUBRIC='secureshop-listings-optimize-v1',SCENARIO='bound_listings_image_optimize';
const LISTINGS_KEY='secureshop.listings.operations.v1';
const exact=(value,keys)=>value&&Object.getPrototypeOf(value)===Object.prototype&&Object.keys(value).sort().join(',')===[...keys].sort().join(',');
const sha=value=>createHash('sha256').update(value).digest('hex');
function assertCounters(value){const keys=['actorTurns','providerSpans','tools','diagnostics','journalEvents','judges','progressWrites'];assert.ok(exact(value,keys));for(const key of keys)assert.ok(Number.isSafeInteger(value[key])&&value[key]>=0);return value;}
async function clickExact(frame,label,selector='button'){
 const handle=await frame.waitForFunction(({label,selector})=>{const rows=[...document.querySelectorAll(selector)].filter(node=>node.textContent.trim()===label&&!node.disabled&&node.getClientRects().length&&getComputedStyle(node).visibility!=='hidden');return rows.length===1?rows[0]:null;},{timeout:30000},{label,selector});
 try{const node=handle.asElement();assert.ok(node);await node.evaluate(value=>value.scrollIntoView({block:'center'}));await node.click();}finally{await handle.dispose();}
}
async function replacePhysical(page,input,value,{verifyCurrent}={}){assert.ok(typeof value==='string'&&value.length>0&&value.length<=4096&&value.isWellFormed());const before=await input.evaluate(node=>node.value);assert.ok(typeof before==='string'&&before.length<=4096);await input.click();for(let index=0;index<=before.length;index++)await page.keyboard.press('ArrowRight');for(let index=0;index<=before.length;index++)await page.keyboard.press('Backspace');assert.equal(await input.evaluate(node=>node.value),'');await page.keyboard.type(value);if(verifyCurrent)await verifyCurrent(value);else assert.equal(await input.evaluate(node=>node.value),value);}
function parentStorageLocation({launchId,generation,sceneId,marker}){assert.match(launchId,UUID);assert.ok(Number.isSafeInteger(generation)&&generation>=1);assert.match(sceneId,UUID);assert.ok(marker===null||marker==='1');const base=`dvaia:secureshop:${launchId.toLowerCase()}:${generation}`;return Object.freeze({base,key:marker===null?base:`${base}:scene:${sceneId.toLowerCase()}`,markerKey:`${base}:scene-storage-v1`});}
async function assertNoOptimizeReference(raw,scopeKey){const {decodeListingsReferences,listingsForScope}=await import(require('node:url').pathToFileURL(require('node:path').join(process.cwd(),'client/src/pages/secureshop/pages/merchant/listingsReferences.mjs')).href);assert.equal(Object.hasOwn(listingsForScope(decodeListingsReferences(raw),scopeKey),'optimize'),false);}
async function assertOptimizeReference(raw,{scopeKey,operationId,chatSource}){const {decodeListingsReferences,listingsForScope}=await import(require('node:url').pathToFileURL(require('node:path').join(process.cwd(),'client/src/pages/secureshop/pages/merchant/listingsReferences.mjs')).href);assert.match(scopeKey,SHA);assert.match(operationId,UUID);assert.ok(exact(chatSource,['sessionId','requestId','proposalId']));for(const value of Object.values(chatSource))assert.match(value,UUID);assert.equal(operationId.toLowerCase(),chatSource.proposalId.toLowerCase());const refs=listingsForScope(decodeListingsReferences(raw),scopeKey);assert.ok(exact(refs,['optimize']));assert.ok(exact(refs.optimize,['scopeKey','operationId','digest','chatSource']));assert.equal(refs.optimize.scopeKey,scopeKey);assert.equal(refs.optimize.operationId,operationId);assert.match(refs.optimize.digest,SHA);assert.deepEqual(refs.optimize.chatSource,chatSource);return refs.optimize;}
function assertEditRequest(request,{expectedPatch,imageUrl}){const expectedKeys=['name','description','price','template_source'];assert.ok(exact(expectedPatch,expectedKeys));assert.equal(Object.hasOwn(expectedPatch,'image_url'),false);assert.ok(exact(request,['patch']));assert.ok(exact(request.patch,[...expectedKeys,'image_url']));assert.deepEqual(request.patch,{...expectedPatch,image_url:imageUrl});return request;}
async function editImageUrl({page,frame,productId,productName,imageUrl,expectedPatch,readProduct}){assert.ok(Number.isSafeInteger(productId)&&productId>0);assert.ok(typeof productName==='string'&&productName);assert.ok(typeof readProduct==='function');assert.ok(imageUrl.length<=4096&&Buffer.byteLength(`${imageUrl} -strip -quality 82 ${imageUrl}.opt.jpg`)<=8192);const row=await frame.waitForFunction(({productId,productName})=>{const rows=[...document.querySelectorAll('tbody tr')].filter(node=>node.textContent.includes(`#${productId}`)&&node.textContent.includes(productName));if(rows.length!==1)return null;const buttons=[...rows[0].querySelectorAll('button[aria-label="Edit"]')].filter(node=>!node.disabled&&node.getClientRects().length);return buttons.length===1?buttons[0]:null;},{timeout:30000},{productId,productName});try{const button=row.asElement();assert.ok(button);await button.click();}finally{await row.dispose();}const input=await frame.waitForFunction(()=>{const labels=[...document.querySelectorAll('label')].filter(node=>node.querySelector('.ss-card__meta')?.textContent==='Images (1-5 URLs)');if(labels.length!==1)return null;const inputs=[...labels[0].querySelectorAll('input')].filter(node=>!node.readOnly&&!node.disabled);return inputs.length>=1?inputs[0]:null;},{timeout:30000});try{const element=input.asElement();assert.ok(element);await replacePhysical(page,element,imageUrl);}finally{await input.dispose();}const pending=page.waitForResponse(response=>response.request().method()==='PUT'&&new URL(response.url()).pathname===`/api/secureshop/merchant/products/${productId}`,{timeout:30000});await clickExact(frame,'Save changes');const response=await pending;assert.equal(response.status(),200);const request=assertEditRequest(JSON.parse(response.request().postData()),{expectedPatch,imageUrl});const product=await readProduct(productId);assert.equal(product.image_url,imageUrl);return Object.freeze({productId,imageUrl,imageUrlSha256:sha(imageUrl),request});}
function optimizeSetupRequest(request){try{if(request.method()!=='POST'||new URL(request.url()).pathname!=='/api/secureshop/agents/merchant/assistant/chat')return null;const body=JSON.parse(request.postData());if(!exact(body,['sessionId','requestId','message','selection'])||!UUID.test(body.sessionId)||!UUID.test(body.requestId)||body.message!=='Prepare image optimization for this listing.'||!exact(body.selection,['choiceId','intent'])||!UUID.test(body.selection.choiceId)||body.selection.intent!=='listing_optimize')return null;return body;}catch{return null;}}
async function prepareOptimizeSetup({page,frame,productName,searchText}){assert.ok(typeof searchText==='string'&&searchText.trim());let stage='open-merchant-assistant',requestDiagnostic={version:1,state:'armed',sessionId:null,requestId:null,choiceId:null,status:null,responseCode:null,responseError:null},requestObservation=null;try{const lane='select[id^="agent-lane-task-merchant-"]',composer='textarea[id^="lane-merchant-assistant-"]';await frame.waitForFunction(selector=>{const rows=[...document.querySelectorAll(selector)].filter(node=>!node.disabled&&node.getClientRects().length&&getComputedStyle(node).visibility!=='hidden');return rows.length===1&&[...rows[0].options].some(option=>option.value==='assistant');},{timeout:30000},lane);assert.deepEqual(await frame.select(lane,'assistant'),['assistant']);stage='fill-merchant-assistant';await frame.waitForFunction(selector=>{const rows=[...document.querySelectorAll(selector)].filter(node=>!node.disabled&&!node.readOnly&&node.getClientRects().length&&getComputedStyle(node).visibility!=='hidden');return rows.length===1;},{timeout:30000},composer);await frame.locator(composer).fill(searchText,{typingThreshold:8193});await frame.waitForFunction((selector,value)=>{const rows=[...document.querySelectorAll(selector)].filter(node=>!node.disabled&&!node.readOnly&&node.getClientRects().length&&getComputedStyle(node).visibility!=='hidden');return rows.length===1&&rows[0].value===value;},{timeout:30000},composer,searchText);await page.keyboard.press('Enter');stage='await-listing-choice';await frame.waitForFunction(name=>[...document.querySelectorAll('[role="group"] .ss-card')].some(card=>card.textContent.includes(name)&&[...card.querySelectorAll('button')].some(button=>button.textContent.trim()==='Prepare image optimization'&&!button.disabled)),{timeout:180000},productName);const prepare=await frame.waitForFunction(name=>{const cards=[...document.querySelectorAll('[role="group"] .ss-card')].filter(card=>card.textContent.includes(name));const buttons=cards.flatMap(card=>[...card.querySelectorAll('button')]).filter(button=>button.textContent.trim()==='Prepare image optimization'&&!button.disabled);return buttons.length===1?buttons[0]:null;},{timeout:30000},productName);requestObservation=new AbortController();let observedRequest=null;const submittedAtRequest=page.waitForRequest(request=>{if(optimizeSetupRequest(request)===null)return false;observedRequest=request;return true;},{timeout:30000,signal:requestObservation.signal}),responded=page.waitForResponse(response=>observedRequest!==null&&response.request()===observedRequest,{timeout:180000,signal:requestObservation.signal});submittedAtRequest.catch(()=>undefined);responded.catch(()=>undefined);try{const button=prepare.asElement();assert.ok(button);await button.click();}finally{await prepare.dispose();}stage='await-listing-setup-request';const submitted=optimizeSetupRequest(await submittedAtRequest);assert.ok(submitted);requestDiagnostic={...requestDiagnostic,state:'submitted',sessionId:submitted.sessionId.toLowerCase(),requestId:submitted.requestId.toLowerCase(),choiceId:submitted.selection.choiceId.toLowerCase()};const setupResponse=await responded;requestObservation.abort();requestObservation=null;requestDiagnostic.status=setupResponse.status();if(setupResponse.status()!==200){let value=null;try{value=JSON.parse(await setupResponse.text());}catch{}requestDiagnostic.responseCode=typeof value?.code==='string'?value.code.slice(0,120):null;requestDiagnostic.responseError=typeof value?.error==='string'?value.error.slice(0,240):null;throw Error(`Role listing setup unavailable (${setupResponse.status()})`);}requestDiagnostic.state='accepted';stage='await-listing-setup';await frame.waitForFunction(name=>{const card=document.querySelector('[aria-label="Listing setup"]');return card?.textContent.includes(`Optimize ${name}`)&&card.textContent.includes('Selected image:')&&[...card.querySelectorAll('a')].some(a=>a.textContent.trim()==='Open in Listings');},{timeout:180000},productName);await clickExact(frame,'Open in Listings','a');}catch(error){requestObservation?.abort();error.v03Stage=stage;error.v03RequestDiagnostic=structuredClone(requestDiagnostic);throw error;}}
function mode(value,expected){assert.ok(exact(value,['version','featureId','policyVersion','effectiveMode','scope']));assert.equal(value.version,1);assert.equal(value.featureId,'listings');assert.ok(typeof value.policyVersion==='string'&&value.policyVersion);assert.equal(value.effectiveMode,expected);assert.deepEqual(value.scope,{kind:'launch_feature',id:'listings'});}
function assertOptimizeResult(value,{operationId,productId,witness,expectedHostname}){assert.ok(exact(value,['ok','operationId','state','modeCapability','productId','additionalCommandObserved','hostname','exitCode']));assert.equal(value.ok,true);assert.equal(value.operationId,operationId);assert.equal(value.state,'completed');assert.equal(value.productId,productId);assert.equal(value.additionalCommandObserved,witness);assert.equal(value.hostname,expectedHostname);assert.ok(Number.isInteger(value.exitCode));mode(value.modeCapability,'vuln');if(witness)assert.equal(value.exitCode,0);else assert.notEqual(value.exitCode,0);return value;}
function assertRecoveredOptimizeResult(value,{operationId,productId,witness,expectedHostname}){assert.ok(exact(value,['ok','operationId','state','productId','additionalCommandObserved','hostname','exitCode']));assert.equal(value.ok,true);assert.equal(value.operationId,operationId);assert.equal(value.state,'completed');assert.equal(value.productId,productId);assert.equal(value.additionalCommandObserved,witness);assert.equal(value.hostname,expectedHostname);assert.ok(Number.isInteger(value.exitCode));if(witness)assert.equal(value.exitCode,0);else assert.notEqual(value.exitCode,0);return value;}
function assertFixedDenial(value,{operationId}){assert.ok(exact(value,['ok','operationId','state','modeCapability']));assert.equal(value.ok,false);assert.equal(value.operationId,operationId);assert.equal(value.state,'denied');mode(value.modeCapability,'fixed');return value;}
function assertRecoveredFixedDenial(value,{operationId}){assert.ok(exact(value,['ok','operationId','state']));assert.equal(value.ok,false);assert.equal(value.operationId,operationId);assert.equal(value.state,'denied');return value;}
async function runOptimize({page,frame,readParentReference,referenceExpected,expectedResult}){assert.equal(typeof readParentReference,'function');await assertNoOptimizeReference(await readParentReference(LISTINGS_KEY),referenceExpected.scopeKey);const submittedAtRequest=page.waitForRequest(request=>request.method()==='POST'&&new URL(request.url()).pathname==='/api/secureshop/merchant/listings/optimize-images',{timeout:180000}).then(async request=>{assert.deepEqual(JSON.parse(request.postData()),{operationId:referenceExpected.operationId,chatSource:referenceExpected.chatSource});return structuredClone(await assertOptimizeReference(await readParentReference(LISTINGS_KEY),referenceExpected));}),pending=page.waitForResponse(response=>response.request().method()==='POST'&&new URL(response.url()).pathname==='/api/secureshop/merchant/listings/optimize-images',{timeout:180000});pending.catch(()=>undefined);await clickExact(frame,'Optimize selected image');const submitted=await submittedAtRequest;const response=await pending;assert.equal(response.status(),200);const result=assertOptimizeResult(JSON.parse(await response.text()),expectedResult);await frame.waitForFunction(({hostname,exit,witness})=>{const text=document.querySelector('[aria-label="Selected listing image"] [role="status"]')?.textContent||'';return text.includes(hostname)&&text.includes(`exit: ${exit}`)&&text.includes(witness?'Additional command observed in the isolated image task':'No image optimization is claimed.');},{timeout:30000},{hostname:result.hostname,exit:String(result.exitCode),witness:result.additionalCommandObserved});assert.deepEqual(await assertOptimizeReference(await readParentReference(LISTINGS_KEY),referenceExpected),submitted);return result;}
async function runFixedOptimize({page,frame,readParentReference,referenceExpected}){await assertNoOptimizeReference(await readParentReference(LISTINGS_KEY),referenceExpected.scopeKey);const submittedAtRequest=page.waitForRequest(request=>request.method()==='POST'&&new URL(request.url()).pathname==='/api/secureshop/merchant/listings/optimize-images',{timeout:180000}).then(async request=>{assert.deepEqual(JSON.parse(request.postData()),{operationId:referenceExpected.operationId,chatSource:referenceExpected.chatSource});return structuredClone(await assertOptimizeReference(await readParentReference(LISTINGS_KEY),referenceExpected));}),pending=page.waitForResponse(response=>response.request().method()==='POST'&&new URL(response.url()).pathname==='/api/secureshop/merchant/listings/optimize-images',{timeout:180000});pending.catch(()=>undefined);await clickExact(frame,'Optimize selected image');const submitted=await submittedAtRequest;const response=await pending;assert.equal(response.status(),200);const result=assertFixedDenial(JSON.parse(await response.text()),referenceExpected);await frame.waitForFunction(()=>document.querySelector('[aria-label="Selected listing image"] [role="status"]')?.textContent.includes('Optimization task: denied. No image optimization is claimed.'),{timeout:30000});assert.deepEqual(await assertOptimizeReference(await readParentReference(LISTINGS_KEY),referenceExpected),submitted);return result;}
async function recoverOptimize({page,getFrame,reopenSetup,readParentReference,referenceExpected,beforeCounters,afterCounters,expectedResult}){assert.equal(typeof reopenSetup,'function');const before=assertCounters(structuredClone(await beforeCounters()));await page.reload({waitUntil:'domcontentloaded'});const frame=await getFrame();await reopenSetup(frame);await assertOptimizeReference(await readParentReference(LISTINGS_KEY),referenceExpected);const pending=page.waitForResponse(response=>response.request().method()==='GET'&&new URL(response.url()).pathname===`/api/secureshop/merchant/listings/operations/${referenceExpected.operationId}`,{timeout:30000});await clickExact(frame,'Check saved optimization');const response=await pending;assert.equal(response.status(),200);const result=assertRecoveredOptimizeResult(JSON.parse(await response.text()),expectedResult);await frame.waitForFunction(({hostname,exit,witness})=>{const text=document.querySelector('[aria-label="Selected listing image"] [role="status"]')?.textContent||'';return text.includes(hostname)&&text.includes(`exit: ${exit}`)&&text.includes(witness?'Additional command observed in the isolated image task':'No image optimization is claimed.');},{timeout:30000},{hostname:result.hostname,exit:String(result.exitCode),witness:result.additionalCommandObserved});assert.deepEqual(assertCounters(structuredClone(await afterCounters())),before);return Object.freeze({frame,result});}
